from pathlib import Path
from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    pts = defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v != bg:
                pts[v].append((r,c))
    # A ray pattern is active when at least three colors each have a diagonal pair.
    pairs = {}
    for color, ps in pts.items():
        found=[]
        for i,(r1,c1) in enumerate(ps):
            for r2,c2 in ps[i+1:]:
                if abs(r2-r1)==1 and abs(c2-c1)==1:
                    found.append(((r1,c1),(r2,c2)))
        if found:
            pairs[color]=found[0]
    if len(pairs)<3:
        return [row[:] for row in grid]
    out=[row[:] for row in grid]
    object_pts=[p for ps in pts.values() for p in ps]
    cr=sum(r for r,c in object_pts)/len(object_pts)
    cc=sum(c for r,c in object_pts)/len(object_pts)
    for color, (p1,p2) in pairs.items():
        d1=(p1[0]-cr)**2+(p1[1]-cc)**2
        d2=(p2[0]-cr)**2+(p2[1]-cc)**2
        outer,inner=(p1,p2) if d1>=d2 else (p2,p1)
        dr=outer[0]-inner[0]; dc=outer[1]-inner[1]
        r,c=outer
        while 0<=r+dr<h and 0<=c+dc<w:
            r+=dr; c+=dc
            if out[r][c]==bg:
                out[r][c]=color
    return out

def make_grid(h,w,bg, cells):
    g=[[bg]*w for _ in range(h)]
    for r,c,v in cells:g[r][c]=v
    return g
